// The one brand-colour table, keyed by brand. `mark` tints the logo itself;
// `chart` is the hue a brand wears in Stats and the balance donuts — its
// logo's own colour, so a bar reads as the provider whose mark sits beside it.
// A monochrome logo (OpenAI, Ollama, xAI, OpenCode…) has no hue to
// lend and falls to the neutral ramp there. Mission Control once kept a
// near-duplicate (`PROVIDER_ACCENT`) and Stats a second chart table
// (`PROVIDER_BRAND_COLOR`); a row's accent depended on which surface drew it.
// Claude Code and Codex are distinct *products*, not just the Anthropic /
// OpenAI providers — they wear their own marks (see PROVIDER_LOGO_IMAGE).
type ModelColorBrand = "qwen" | "llama" | "kimi" | "minimax" | "sakana" | "huggingface";
const BRAND_COLOR: Partial<Record<BrandKey | ModelColorBrand, { mark?: string; chart?: string }>> = {
  anthropic: { mark: "#D97757", chart: "#D97757" },
  "claude-code": { mark: "#D97757", chart: "#D97757" },
  openai: { mark: "var(--fg-strong)" },
  // The cloud's lilac→blue gradient, taken at its middle.
  codex: { mark: "#6474FF", chart: "#6474FF" },
  opencode: { mark: "var(--fg-strong)" },
  xai: { mark: "var(--fg-strong)" },
  // The amber between the pixel M's yellow and red — its red end sits too
  // close to Anthropic's clay for two neighbouring bars.
  mistral: { chart: "#F5A524" },
  gemini: { chart: "#3186FF" },
  openrouter: { mark: "#4A6CF7", chart: "#6467F2" },
  deepseek: { mark: "#4D6BFE", chart: "#4D6BFE" },
  omp: { mark: "#7C6BAE", chart: "#7C6BAE" },
  // Model-only makers use the hues of the logo assets shipped in /public.
  qwen: { chart: "#082DFF" },
  llama: { chart: "#0081FB" },
  kimi: { chart: "#1783FF" },
  minimax: { chart: "#F44454" },
  sakana: { chart: "#E10600" },
  huggingface: { chart: "#FFD21E" },
};

function brandColor(id: string): { mark?: string; chart?: string } | undefined {
  return BRAND_COLOR[providerBrand(id) as BrandKey | ModelColorBrand];
}

/** A provider's brand colour, or `undefined` for one with no mark of its own. */
export function providerBrandColor(id: ProviderId | BrandKey): string | undefined {
  return brandColor(id)?.mark;
}

/** The chart-ramp step a provider's brand wears (Stats, balance donuts), or
 *  `undefined` for a brand with no hue of its own. Accepts a run source too,
 *  since a delegate is both a source and a Provider. */
export function providerChartColor(id: string): string | undefined {
  return brandColor(id)?.chart;
}

const PROVIDER_LOGO_IMAGE: Partial<Record<BrandKey, string>> = {
  ollama: "/ollama-logo.png",
  gemini: "/gemini-logo.png",
  mistral: "/mistral-logo.png",
  deepseek: "/deepseek-logo.png",
  amp: "/amp-logo.svg",
  cursor: "/cursor-logo.svg",
  factory: "/factory-logo.svg",
  // Primer Octicons copilot-24 (MIT, GitHub) — a black mark, inverted on dark.
  copilot: "/copilot-logo.svg",
  "claude-code": "/claude-code-logo.png",
  codex: "/codex-logo.png",
};

// How each image mark reacts to theme:
// - "provider-logo-img" (default): dark mark, inverted to white on dark themes.
// - "color-logo-img": inherently colored, never inverted (keeps brand color).
// - "white-logo-img": white mark, inverted to dark on light themes.
const PROVIDER_LOGO_IMAGE_CLASS: Partial<Record<BrandKey, string>> = {
  "claude-code": "color-logo-img",
  // A lilac→blue cloud with a white prompt glyph — keeps its colour.
  codex: "color-logo-img",
  // DeepSeek's whale is brand blue on transparent — inverting it would turn it
  // into an unreadable yellow.
  deepseek: "color-logo-img",
  amp: "color-logo-img",
  cursor: "color-logo-img",
  factory: "color-logo-img",
  // Gemini's 2025 star carries its own red→blue→green gradient.
  gemini: "color-logo-img",
  // Mistral's pixel M is a yellow→red gradient; inverting it would ruin it.
  mistral: "color-logo-img",
};

/** The mark for a Provider id or a bare brand key. A registry row's `brand`
 *  picks the drawing; `auto`, `custom:*` and `cli:*` have marks of their own. */
export function ProviderLogo({ id, size = 14 }: { id: ProviderId | BrandKey; size?: number }) {
  const brand = providerBrand(id) as BrandKey | "auto";
  if (brand === "hermes") {
    return <TwoToneMark light="/hermes-logo.png" dark="/hermes-logo-dark.png" size={size} />;
  }
  if (brand === "opencode") {
    return (
      <TwoToneMark
        light="/opencode-logo-light.svg"
        dark="/opencode-logo-dark.svg"
        size={size}
      />
    );
  }

  const image = PROVIDER_LOGO_IMAGE[brand as BrandKey];
  if (image) {
    return (
      <BrandImage
        className={PROVIDER_LOGO_IMAGE_CLASS[brand as BrandKey] ?? "provider-logo-img"}
        src={image}
        size={size}
      />
    );
  }

  const color = providerBrandColor(id) ?? "currentColor";
  const base = {
    width: size,
    height: size,
    viewBox: "0 0 24 24",
    "aria-hidden": true as const,
    style: { flexShrink: 0, color },
  };
  const mark = BRAND_MARKS[brand as BrandKey];
  if (mark) {
    return (
      // Monochrome: drawn at full strength, like the OpenAI and xAI marks.
      <svg
        {...base}
        style={{ ...base.style, color: providerBrandColor(id) ?? "var(--fg-strong)" }}
        viewBox={mark.viewBox ?? base.viewBox}
        fill="currentColor"
        fillRule={mark.fillRule ?? "evenodd"}
      >
        <g transform={mark.transform}>
          {mark.paths.map((p, i) => (
            <path key={i} d={p.d} fillOpacity={p.opacity} />
          ))}
        </g>
      </svg>
    );
  }
  const path = BRAND_LOGO_PATHS[brand as BrandKey];
  if (path) {
    return (
      <svg {...base} fill="currentColor">
        <path d={path} />
      </svg>
    );
  }
  const line = {
    ...base,
    fill: "none",
    stroke: "currentColor",
    strokeLinecap: "round" as const,
    strokeLinejoin: "round" as const,
  };
  // Self-hosted (custom:*) endpoints — a server-rack glyph with status LEDs,
  // so "bring your own datacenter" reads at a glance instead of a bare dot.
  if (id.startsWith("custom:")) {
    return (
      <svg {...line} strokeWidth="1.7">
        <rect x="3" y="4" width="18" height="7" rx="2" />
        <rect x="3" y="13" width="18" height="7" rx="2" />
        <path d="M7 7.5h0M7 16.5h0" strokeWidth="2.4" />
      </svg>
    );
  }
  if (id.startsWith("cli:")) {
    return (
      <svg {...line} strokeWidth="1.8">
        <rect x="3" y="4" width="18" height="16" rx="3" />
        <path d="M7 9l3 3-3 3M12 15h5" />
      </svg>
    );
  }
  switch (brand) {
    case "auto":
      // The router: three lanes meeting one road. Hand-drawn like the other
      // provider marks, in currentColor so it themes with the row.
      return (
        <svg {...line} strokeWidth="1.7">
          <path d="M4 6h5l5 6-5 6H4M4 12h5" />
          <path d="M14 12h6M17 9l3 3-3 3" />
        </svg>
      );
    case "llamacpp":
      // Llama project's mark from llama.app, rendered in the theme foreground.
      return (
        <svg {...base} viewBox="0 0 600 600" fill="currentColor">
          <path d="M600 392L504.249 558L504.137 557.929C487.252 584.069 458.193 600 426.864 600H120L240 392H600Z" />
          <path d="M240 392H0L199.602 46.0254C216.032 17.5463 246.411 0 279.29 0H466.154L240 392Z" />
        </svg>
      );
    case "mlx":
      // MLX wordmark: bold "ML" in the foreground color + a muted-gray "X",
      // matching Apple's mark. Rendered as a transparent SVG (no baked
      // black/white tile) so it themes cleanly at any size.
      return (
        <svg {...base} fill="none">
          <text
            x="12"
            y="16"
            textAnchor="middle"
            fontFamily="'Atkinson Hyperlegible', system-ui, sans-serif"
            fontSize="9"
            fontWeight="800"
            letterSpacing="-0.4"
          >
            <tspan fill="currentColor">ML</tspan>
            <tspan fill="#8a8a8a">X</tspan>
          </text>
        </svg>
      );
    case "lmstudio":
      return (
        <svg {...line} strokeWidth="1.6">
          <rect x="3" y="3" width="18" height="18" rx="5" />
          <path d="M9 8v8M15 8v8" />
        </svg>
      );
    case "omp":
      // Oh My Pi's "Pi" mark (a blocky P + i dot). The source art is solid
      // white, so render it with currentColor (tinted by PROVIDER_LOGO_COLOR)
      // instead of a fixed fill — that way it survives Klide's light themes.
      return (
        <svg {...base} viewBox="0 0 800 800" fill="currentColor">
          <path
            fillRule="evenodd"
            d="M165.29 165.29 H517.36 V400 H400 V517.36 H282.65 V634.72 H165.29 Z M282.65 282.65 V400 H400 V282.65 Z"
          />
          <path d="M517.36 400 H634.72 V634.72 H517.36 Z" />
        </svg>
      );
    default:
      return (
        <svg {...base} fill="currentColor">
          <circle cx="12" cy="12" r="4" />
        </svg>
      );
  }
}

